import { describe, expect, it } from 'vitest'
import { day } from './dates'
import { criticalPoints, generateLog } from './gen'
import { HORIZON, SCENARIO } from './log'
import { referenceQuery } from './reference'
import { DEFAULT_CONFIG, materialize } from './strategies/index'
import type { Config, Strategy } from './strategies/index'
import { hybrid } from './strategies/hybrid'
import { snapshots } from './strategies/snapshots'
import { snapshotStale } from './strategies/snapshotStale'
import { ATTRS } from './types'
import type { Fact } from './types'

const INTERVALS = [7, 30, 90]
const cfgWith = (snapshotInterval: number): Config => ({ snapshotInterval })

/**
 * Same approach as the sweep in strategies.test.ts: the value surface only
 * breaks at recorded coordinates, so sweeping the critical points is
 * exhaustive rather than a sample.
 */
function sweep<S>(strategy: Strategy<S>, log: readonly Fact[], cfg: Config): void {
  const { state } = materialize(strategy, log, cfg)
  const valids = criticalPoints(log.map((f) => f.validFrom), HORIZON.start, HORIZON.end)
  const systems = criticalPoints(log.map((f) => f.systemTime), HORIZON.start, HORIZON.end)

  for (const attr of ATTRS) {
    for (const v of valids) {
      for (const s of systems) {
        const expected = referenceQuery(log, attr, v, s)
        const actual = strategy.query(state, attr, v, s)
        if (actual !== expected) {
          throw new Error(
            `${strategy.name} (snapshotInterval=${cfg.snapshotInterval}): ${attr} at valid=${v} ` +
            `system=${s} gave ${String(actual)}, oracle says ${String(expected)}`,
          )
        }
      }
    }
  }
}

describe('the scenario', () => {
  it('snapshots agrees with the oracle everywhere', () => {
    sweep(snapshots, SCENARIO, DEFAULT_CONFIG)
  })

  for (const interval of INTERVALS) {
    it(`hybrid agrees with the oracle everywhere, snapshotInterval=${interval}`, () => {
      sweep(hybrid, SCENARIO, cfgWith(interval))
    })
  }
})

describe('generated histories', () => {
  for (let seed = 0; seed < 30; seed++) {
    const log = generateLog(seed, 14)

    it(`snapshots agrees with the oracle, seed ${seed}`, () => {
      sweep(snapshots, log, DEFAULT_CONFIG)
    })

    for (const interval of INTERVALS) {
      it(`hybrid agrees with the oracle, seed ${seed}, snapshotInterval=${interval}`, () => {
        sweep(hybrid, log, cfgWith(interval))
      })
    }
  }
})

describe('snapshotStale: the deliberately incorrect strategy', () => {
  const { state } = materialize(snapshotStale, SCENARIO, DEFAULT_CONFIG)

  // The rectangle where the bug bites: the snapshot at 1 April carries
  // salary = 60,000 because only the manager changed that day, and the raise
  // backdated to 1 March — recorded 10 June — never goes back to rebuild it.
  const RECT_VALID_FROM = day(2026, 4, 1)
  const RECT_SYSTEM_FROM = day(2026, 6, 10)

  it('agrees with the oracle until the backdated raise is recorded', () => {
    const beforeRaiseRecorded = day(2026, 6, 9)
    expect(referenceQuery(SCENARIO, 'salary', RECT_VALID_FROM, beforeRaiseRecorded)).toBe(60_000)
    expect(snapshotStale.query(state, 'salary', RECT_VALID_FROM, beforeRaiseRecorded)).toBe(60_000)
  })

  it('diverges once the raise lands: stale still says 60,000, oracle says 72,000', () => {
    expect(referenceQuery(SCENARIO, 'salary', RECT_VALID_FROM, RECT_SYSTEM_FROM)).toBe(72_000)
    expect(snapshotStale.query(state, 'salary', RECT_VALID_FROM, RECT_SYSTEM_FROM)).toBe(60_000)
  })

  it('disagrees with the oracle throughout the rectangle, always 60,000 vs 72,000', () => {
    const valids = criticalPoints(SCENARIO.map((f) => f.validFrom), HORIZON.start, HORIZON.end)
      .filter((v) => v >= RECT_VALID_FROM)
    const systems = criticalPoints(SCENARIO.map((f) => f.systemTime), HORIZON.start, HORIZON.end)
      .filter((s) => s >= RECT_SYSTEM_FROM)

    for (const v of valids) {
      for (const s of systems) {
        expect(referenceQuery(SCENARIO, 'salary', v, s)).toBe(72_000)
        expect(snapshotStale.query(state, 'salary', v, s)).toBe(60_000)
      }
    }
  })

  it('agrees with the oracle everywhere outside the rectangle', () => {
    const valids = criticalPoints(SCENARIO.map((f) => f.validFrom), HORIZON.start, HORIZON.end)
    const systems = criticalPoints(SCENARIO.map((f) => f.systemTime), HORIZON.start, HORIZON.end)

    for (const attr of ATTRS) {
      for (const v of valids) {
        for (const s of systems) {
          const inRectangle = v >= RECT_VALID_FROM && s >= RECT_SYSTEM_FROM
          if (inRectangle) continue
          const expected = referenceQuery(SCENARIO, attr, v, s)
          const actual = snapshotStale.query(state, attr, v, s)
          expect(actual, `attr=${attr} valid=${v} system=${s}`).toBe(expected)
        }
      }
    }
  })
})

/**
 * Analytic cost model for the five representations.
 *
 * This is a MODEL, not a benchmark: every number below is a closed-form
 * function of the stated mechanics in strategies/*.ts, not a measurement.
 * Nothing here runs a strategy, generates data, or times anything. Where the
 * mechanics genuinely underdetermine a coefficient (e.g. "roughly how many
 * distinct valid-time points does N facts produce?"), the coefficient is a
 * named constant with a comment giving the reasoning, so it can be argued
 * with rather than taken on faith.
 *
 * Throughout, "records" means the unit each strategy actually stores:
 * one fact for deltas, one bitemporal row for intervals, one attribute-value
 * for snapshots (a full-entity snapshot is `attrs` records, which is the
 * point being modelled — see storage() below).
 */

export type CostParams = {
  /** N — total facts recorded so far. The axis every "as history grows" claim runs over. */
  facts: number
  /** A — attributes tracked per entity (ATTRS.length in this app, generalised here). */
  attrs: number
  /** H — length of the modelled horizon, in days. Only the day-grid strategies (hybrid) need a calendar. */
  horizonDays: number
  /** k — hybrid's snapshot grid spacing, in days. */
  snapshotInterval: number
  /** d — how far back a retroactive fact reaches, as a fraction of history already recorded. 0 = touches nothing behind it, 1 = reaches all the way to the start. */
  retroDepth: number
}

export type CostModel = {
  key: string
  /** Records currently stored, after `facts` facts have been applied. */
  storage(p: CostParams): number
  /** Records touched to answer one point query (one attr, one valid time, one system time). */
  read(p: CostParams): number
  /** Records written by the next fact, given it arrives in order (validFrom after everything known). */
  append(p: CostParams): number
  /** Records written or invalidated by the next fact, given it is retroactive at depth `retroDepth`. */
  retro(p: CostParams): number
  /** Big-O labels for the table. Same four measures, in the same order. */
  notation: { storage: string; read: string; append: string; retro: string }
}

// Defensive floor for values used as divisors. Callers are expected to pass
// horizonDays >= 1 and snapshotInterval >= 1 (a zero-length horizon or a
// zero-day grid is not a representable configuration), but the cost
// functions themselves must stay finite under a blind parameter sweep, so
// every division goes through this rather than trusting the caller.
const atLeast1 = (n: number): number => Math.max(n, 1)

// --- deltas ---------------------------------------------------------------
//
// storage: exactly the facts, one record each — nothing is derived or duplicated.
// read: query() has no index to consult, so it walks every fact in the log
//   (see deltas.ts: readCost is state.facts.length, not filtered by attr).
// append: one fact in, one record out.
// retro: a retroactive fact is still just one fact — appending it costs the
//   same as appending any other. The cost of "being retroactive" for deltas
//   is paid by every read from then on (already captured by read growing
//   with N), never by the write itself. That asymmetry is the whole pitch
//   of the strategy, so retro() deliberately does NOT depend on retroDepth.
const deltasModel: CostModel = {
  key: 'deltas',
  storage: (p) => p.facts,
  read: (p) => p.facts,
  append: () => 1,
  retro: () => 1,
  notation: { storage: 'O(N)', read: 'O(N)', append: 'O(1)', retro: 'O(1)' },
}

// --- intervals --------------------------------------------------------------
//
// The mechanics (intervals.ts apply()): a new fact for an attribute finds the
// currently open row for that attribute and clips against it — even an
// in-order append closes that row (system-time bound) and reopens the
// surviving remainder, because the old row's validTo was INF and now has to
// be bounded at the new fact's validFrom. So the "rewrite on write" cost is
// not special to retroactive facts, it happens on every apply(); retroactive
// facts just have more rows in their way.
//
// INTERVAL_ROWS_PER_FACT: tracing apply() for a steady stream of in-order
// facts on one attribute — each fact replaces the one open row with a closed
// copy + a reopened remainder (net +1 for that row) and adds its own new row
// (+1) — settles at 2 stored rows per fact. This is a judgement call in the
// sense that it assumes one attribute has at most one open row at a time
// (true as long as retroactive facts are clipped to the next known
// validFrom, which is exactly what apply() does — see the comment in
// intervals.ts about not swallowing later changes).
const INTERVAL_ROWS_PER_FACT = 2

// INTERVALS_APPEND_OPS: the per-append row-touch count straight off the same
// trace — 1 rewritten (close the old open row) + 2 written (its reopened
// remainder, plus the new fact's own row) = 3. Independent of N: only the
// one currently-open row for this attribute is ever touched by an in-order
// append, which is why intervals' write path is O(1) despite being a
// rewriting strategy.
const INTERVALS_APPEND_OPS = 3

// A retroactive fact is not clipped only against the single row it lands in
// forwards — per the panel's own framing (PLAN.md: "the interval table
// splits a rectangle and rewrites everything downstream of it"), reaching
// depth d into H means every row whose validity starts at or after that
// point is closed and reopened against the new fact. Modelled as: touch a
// `retroDepth` fraction of the rows currently stored, at the same 2-ops-per-
// row rate the append trace established (1 close + 1 reopen), plus the O(1)
// cost of writing the correction's own row.
const intervalsModel: CostModel = {
  key: 'intervals',
  storage: (p) => p.facts * INTERVAL_ROWS_PER_FACT,
  // Indexed lookup: find the rectangle containing (attr, valid, system).
  // Independent of N and of attrs — a matching row carries one value.
  read: () => 1,
  append: () => INTERVALS_APPEND_OPS,
  // Constant, and NOT the O(d·N) write amplification interval tables are
  // usually accused of. The reason is worth stating, because it is the most
  // counter-intuitive number on this panel.
  //
  // A fact here carries a validFrom and no validTo: it is open-ended, holding
  // until the next fact supersedes it. Open rows therefore tile valid time
  // with boundaries exactly at recorded valid times, so a new fact always
  // lands inside precisely ONE open row, and intervals.ts clips it at the
  // next boundary. One row closed, at most two reopened — however far back
  // the fact reaches.
  //
  // Amplification is real, but it belongs to a model this one does not have:
  // facts carrying an explicit valid RANGE. "Salary was wrong for all of Q1"
  // spans every row in that quarter and rewrites each. Charging that cost
  // here would be modelling a different implementation than the one shipped,
  // which costClaims.test.ts exists to prevent.
  retro: () => INTERVALS_APPEND_OPS,
  notation: { storage: 'O(N)', read: 'O(1)', append: 'O(1)', retro: 'O(1)' },
}

// --- snapshots --------------------------------------------------------------
//
// "One full entity snapshot per distinct valid time, stored bitemporally."
// Two judgement calls carry this model:
//
// SNAPSHOT_DISTINCT_TIMES ≈ facts: approximating the number of distinct valid
// times by the number of facts is an upper bound (two facts landing on the
// same valid time would share a snapshot), but it is the common case for
// this app's per-attribute fact stream and keeps the model a single N term
// rather than inventing an unfounded compression ratio.
//
// storage = distinct times * attrs: this is the point of the strategy. Every
// snapshot carries a value for every attribute, changed or not, so N facts
// (each touching one attribute) still cost N*A records stored — the
// "duplicated state" the product brief calls out by name.
//
// SNAPSHOT_CLOSE_OVERHEAD: to stay correct, writing a new snapshot must also
// bitemporally close the previous one (set its systemTo) so that a later
// retroactive correction can find "every snapshot at or after v" — the exact
// set retro() below has to invalidate. That close-out is 1 extra record on
// every append. It is also exactly the bookkeeping snapshotStale skips.
const SNAPSHOT_CLOSE_OVERHEAD = 1

const snapshotsModel: CostModel = {
  key: 'snapshots',
  storage: (p) => p.facts * p.attrs,
  // Direct lookup of the one bitemporal snapshot row valid at the coordinate;
  // reading one field out of it is a fixed A-sized structure access.
  read: (p) => p.attrs,
  append: (p) => p.attrs + SNAPSHOT_CLOSE_OVERHEAD,
  // Every snapshot at or after the retroactive valid time is invalidated and
  // rebuilt in full (all A attributes, not just the one that changed) —
  // count of affected snapshots ~ retroDepth * facts, each costing `attrs`.
  retro: (p) => p.retroDepth * p.facts * p.attrs,
  notation: { storage: 'O(N·A)', read: 'O(A)', append: 'O(A)', retro: 'O(d·N·A)' },
}

// --- snapshotStale ------------------------------------------------------------
//
// Same stored shape as snapshots (full A-valued rows — PLAN.md is explicit
// that the broken row's stored snapshot at the trap's valid time really does
// carry the old salary alongside the new manager), so storage() and read()
// are identical. The divergence is entirely in what the write path skips:
// it never performs the SNAPSHOT_CLOSE_OVERHEAD bookkeeping (there is no
// reason to, since it never walks "every snapshot at or after v"), and on a
// retroactive fact it does not invalidate anything downstream — it just
// records the new snapshot and stops. That is simultaneously why it is
// cheaper to write and why it is wrong: every already-materialized snapshot
// at or after the retroactive valid time is left holding stale attribute
// values, which is exactly the silent-revert trap the panel demonstrates.
const snapshotStaleModel: CostModel = {
  key: 'snapshotStale',
  storage: (p) => p.facts * p.attrs,
  read: (p) => p.attrs,
  append: (p) => p.attrs,
  retro: (p) => p.attrs,
  notation: { storage: 'O(N·A)', read: 'O(A)', append: 'O(A)', retro: 'O(A)' },
}

// --- hybrid -------------------------------------------------------------------
//
// Snapshots on a fixed day grid (spacing k = snapshotInterval, over a horizon
// of H days), plus the full log. Reads take the nearest grid snapshot and
// replay forward to the query point.
//
// HYBRID_FACT_DENSITY: the one judgement call here — facts are assumed to
// arrive roughly uniformly over the horizon, so a k-day replay window holds
// on average (facts / H) * k facts. A bursty log would make some windows
// longer and others shorter; uniform density is the honest "no better
// information" baseline the product brief's sliders are built to explore.
const hybridModel: CostModel = {
  key: 'hybrid',
  // The full log (N records) plus one A-valued snapshot per grid point.
  // Grid points = H / k, so storage falls as the grid widens — the other
  // half of the tradeoff read() shows rising.
  storage: (p) => p.facts + (p.horizonDays / atLeast1(p.snapshotInterval)) * p.attrs,
  // Fetch the nearest snapshot (attrs records) then replay the bounded
  // window back to the query point (average window size below).
  read: (p) => p.attrs + (p.facts / atLeast1(p.horizonDays)) * p.snapshotInterval,
  // Appending to the log is O(1); the periodic grid snapshot is a scheduled
  // O(attrs) event amortised over the facts that occur inside one grid cell,
  // not a cost paid by any single fact.
  append: (p) => 1 + p.attrs / atLeast1(p.snapshotInterval),
  // A retroactive fact is appended to the log (O(1)) and invalidates the
  // grid snapshots at or after its valid time — far fewer of them than plain
  // snapshots pays, because the grid is coarser than the fact stream by a
  // factor of k. Affected grid points ~ retroDepth * H / k, each rebuilt in
  // full (attrs records).
  retro: (p) => 1 + p.retroDepth * (p.horizonDays / atLeast1(p.snapshotInterval)) * p.attrs,
  notation: {
    storage: 'O(N + H/k·A)',
    read: 'O(A + N·k/H)',
    // Not O(1): flat in the number of facts, but the scheduled grid snapshot
    // is A records amortised over a k-day cell. Writing O(1) here would let a
    // reader skimming the table mistake it for deltas' genuinely constant
    // append, which is the one comparison this row must not fudge.
    append: 'O(1 + A/k)',
    retro: 'O(1 + d·H/k·A)',
  },
}

export const COST_MODELS: Record<string, CostModel> = {
  deltas: deltasModel,
  intervals: intervalsModel,
  snapshots: snapshotsModel,
  snapshotStale: snapshotStaleModel,
  hybrid: hybridModel,
}

/**
 * Sample one measure of one model across a range of fact counts, holding
 * every other parameter at `base`. This is the shape the scale panel plots:
 * curves over history size, with the snapshot-interval and retro-depth
 * sliders supplying `base` rather than being swept themselves.
 */
export function costCurve(
  measure: (p: CostParams) => number,
  base: CostParams,
  range: readonly number[],
): { x: number; y: number }[] {
  return range.map((facts) => ({ x: facts, y: measure({ ...base, facts }) }))
}

import { describe, expect, it } from 'vitest'
import { COST_MODELS, costCurve } from './cost'
import type { CostModel, CostParams } from './cost'

/**
 * These tests check the CLAIMS the scale panel makes about the five
 * representations, not the arithmetic inside cost.ts. If a formula changes
 * but the underlying architectural story stays true, these should still
 * pass; if the story stops being true, these should fail even if the new
 * arithmetic is internally consistent.
 */

const BASE: CostParams = {
  facts: 1_000,
  attrs: 2,
  horizonDays: 365,
  snapshotInterval: 30,
  retroDepth: 0.4,
}

const models = COST_MODELS as Record<
  'deltas' | 'intervals' | 'snapshots' | 'snapshotStale' | 'hybrid',
  CostModel
>

describe('deltas read grows with history, direct-lookup reads do not', () => {
  const small = { ...BASE, facts: 100 }
  const large = { ...BASE, facts: 100_000 }

  it('deltas read scales up with N', () => {
    expect(models.deltas.read(large)).toBeGreaterThan(models.deltas.read(small) * 100)
  })

  it('intervals read does not grow with N', () => {
    expect(models.intervals.read(large)).toBe(models.intervals.read(small))
  })

  it('snapshots read does not grow with N', () => {
    expect(models.snapshots.read(large)).toBe(models.snapshots.read(small))
  })
})

describe('snapshots duplicate state relative to deltas, and the gap widens', () => {
  it('snapshots storage exceeds deltas storage', () => {
    expect(models.snapshots.storage(BASE)).toBeGreaterThan(models.deltas.storage(BASE))
  })

  it('the storage gap widens as N grows', () => {
    const gapAt = (facts: number) => {
      const p = { ...BASE, facts }
      return models.snapshots.storage(p) - models.deltas.storage(p)
    }
    const gapSmall = gapAt(100)
    const gapLarge = gapAt(100_000)
    expect(gapSmall).toBeGreaterThan(0)
    expect(gapLarge).toBeGreaterThan(gapSmall)
  })
})

describe('hybrid: snapshot interval trades storage against read cost', () => {
  it('storage falls and read rises as the grid widens — the tradeoff is visible', () => {
    const tight = { ...BASE, snapshotInterval: 1 }
    const wide = { ...BASE, snapshotInterval: 200 }

    const storageTight = models.hybrid.storage(tight)
    const storageWide = models.hybrid.storage(wide)
    const readTight = models.hybrid.read(tight)
    const readWide = models.hybrid.read(wide)

    expect(storageWide).toBeLessThan(storageTight)
    expect(readWide).toBeGreaterThan(readTight)
  })

  it('the two measures move in opposite directions across the whole sweep', () => {
    const intervals = [1, 5, 10, 30, 90, 200, 365]
    const storages = intervals.map((snapshotInterval) =>
      models.hybrid.storage({ ...BASE, snapshotInterval }),
    )
    const reads = intervals.map((snapshotInterval) => models.hybrid.read({ ...BASE, snapshotInterval }))

    for (let i = 1; i < intervals.length; i++) {
      expect(storages[i]).toBeLessThanOrEqual(storages[i - 1]!)
      expect(reads[i]).toBeGreaterThanOrEqual(reads[i - 1]!)
    }
    // and not merely flat — the tradeoff has to actually move.
    expect(storages.at(-1)).toBeLessThan(storages[0]!)
    expect(reads.at(-1)).toBeGreaterThan(reads[0]!)
  })
})

describe('retroactive depth: snapshots pays for it, intervals and deltas do not', () => {
  it('snapshots retro cost rises with retroDepth', () => {
    const shallow = models.snapshots.retro({ ...BASE, retroDepth: 0 })
    const deep = models.snapshots.retro({ ...BASE, retroDepth: 1 })
    expect(deep).toBeGreaterThan(shallow)
  })

  it('intervals retro cost is flat, because facts here are open-ended', () => {
    // Not the write amplification interval tables are usually accused of. A
    // fact carries a validFrom and no validTo, so it always lands inside
    // exactly one open row and is clipped at the next boundary: one row
    // closed, at most two reopened, however far back it reaches. Amplification
    // needs facts carrying an explicit valid range, which this model does not
    // have. costClaims.test.ts holds the model to the implementation on this.
    const shallow = models.intervals.retro({ ...BASE, retroDepth: 0 })
    const deep = models.intervals.retro({ ...BASE, retroDepth: 1 })
    expect(deep).toBe(shallow)
  })

  it('deltas retro cost is flat regardless of retroDepth', () => {
    const shallow = models.deltas.retro({ ...BASE, retroDepth: 0 })
    const deep = models.deltas.retro({ ...BASE, retroDepth: 1 })
    expect(deep).toBe(shallow)
  })
})

describe('the tempting bug: snapshotStale writes cheaper than correct snapshots', () => {
  it('append is strictly cheaper for snapshotStale than for snapshots', () => {
    expect(models.snapshotStale.append(BASE)).toBeLessThan(models.snapshots.append(BASE))
  })

  it('holds across a range of attribute counts, not just the default', () => {
    for (const attrs of [1, 2, 5, 20]) {
      const p = { ...BASE, attrs }
      expect(models.snapshotStale.append(p)).toBeLessThan(models.snapshots.append(p))
    }
  })
})

describe('every model stays finite and non-negative across a wide parameter sweep', () => {
  const factsValues = [0, 1, 50, 10_000]
  const attrsValues = [1, 2, 8]
  const horizonDaysValues = [1, 30, 365, 3650]
  const retroDepthValues = [0, 0.3, 1]
  // snapshotInterval edge cases called out explicitly: 1, and equal to the horizon.
  const snapshotIntervalOf = (horizonDays: number) => [1, horizonDays]

  const measureNames = ['storage', 'read', 'append', 'retro'] as const

  for (const [key, model] of Object.entries(models)) {
    it(`${key}: finite, non-negative for every combination in the sweep`, () => {
      for (const facts of factsValues) {
        for (const attrs of attrsValues) {
          for (const horizonDays of horizonDaysValues) {
            for (const snapshotInterval of snapshotIntervalOf(horizonDays)) {
              for (const retroDepth of retroDepthValues) {
                const p: CostParams = { facts, attrs, horizonDays, snapshotInterval, retroDepth }
                for (const measure of measureNames) {
                  const value = model[measure](p)
                  expect(Number.isFinite(value), `${key}.${measure}(${JSON.stringify(p)})`).toBe(
                    true,
                  )
                  expect(value, `${key}.${measure}(${JSON.stringify(p)})`).toBeGreaterThanOrEqual(
                    0,
                  )
                }
              }
            }
          }
        }
      }
    })
  }
})

describe('notation labels exist for every measure of every model', () => {
  const measureNames = ['storage', 'read', 'append', 'retro'] as const

  for (const [key, model] of Object.entries(models)) {
    it(`${key} has non-empty notation for all four measures`, () => {
      for (const measure of measureNames) {
        const label = model.notation[measure]
        expect(typeof label).toBe('string')
        expect(label.length).toBeGreaterThan(0)
      }
    })
  }
})

describe('costCurve', () => {
  it('samples the given measure over the given range, holding the rest of the params fixed', () => {
    const range = [0, 10, 100, 1_000]
    const points = costCurve(models.deltas.storage, BASE, range)

    expect(points).toHaveLength(range.length)
    points.forEach((point, i) => {
      expect(point.x).toBe(range[i])
      expect(point.y).toBe(models.deltas.storage({ ...BASE, facts: range[i]! }))
    })
  })
})

import { describe, expect, it } from 'vitest'
import { COST_MODELS } from './cost'
import type { CostParams } from './cost'
import { day } from './dates'
import { HORIZON, makeFact } from './log'
import { DEFAULT_CONFIG, materialize } from './strategies/index'
import { STRATEGIES } from './strategies/registry'
import type { Fact } from './types'

/**
 * The cost panel is an analytic model, not a benchmark — but a model that
 * contradicts the code beside it is worse than no model. This file does not
 * check the numbers, which are deliberately abstract; it checks that each
 * measure GROWS the way the implementation grows. That is the claim a reader
 * of the panel actually takes away, and the one that silently rots.
 *
 * It caught a real drift already: the intervals model charged O(d·N) for a
 * retroactive write, borrowed from the usual write-amplification story, while
 * the implementation is O(1) because open-ended facts always land inside a
 * single row and get clipped at the next boundary.
 */

function inOrderLog(n: number): Fact[] {
  const log: Fact[] = []
  for (let i = 0; i < n; i++) {
    const d = day(2026, 1, 1) + i * 5
    log.push(makeFact('salary', 1000 + i, d, d, `b${i}`))
  }
  return log
}

/** Work done by one maximally retroactive fact applied to a log of n facts. */
function observedRetro(key: string, n: number): number {
  const strategy = STRATEGIES.find((s) => s.key === key)!
  const base = inOrderLog(n)
  const { state } = materialize(strategy, base, DEFAULT_CONFIG)
  const clock = day(2026, 1, 1) + n * 5 + 10
  const fact = makeFact('salary', 9, day(2026, 1, 2), clock, 'retro')
  const { ops } = strategy.apply(state, fact, DEFAULT_CONFIG)
  return ops.written + ops.rewritten + ops.invalidated
}

function modelRetro(key: string, n: number): number {
  const p: CostParams = {
    facts: n,
    attrs: 2,
    horizonDays: HORIZON.end - HORIZON.start,
    snapshotInterval: DEFAULT_CONFIG.snapshotInterval,
    retroDepth: 1,
  }
  return COST_MODELS[key]!.retro(p)
}

/** Does this measure grow with the size of the history, or not? */
const grows = (small: number, large: number) => large > small * 2

describe('the model grows the way the code grows', () => {
  for (const strategy of STRATEGIES) {
    it(`${strategy.name}: retroactive write`, () => {
      const observed = grows(observedRetro(strategy.key, 8), observedRetro(strategy.key, 32))
      const modelled = grows(modelRetro(strategy.key, 8), modelRetro(strategy.key, 32))
      expect(
        modelled,
        observed
          ? 'the implementation scales with history here; the model says it does not'
          : 'the model charges for scale the implementation does not pay',
      ).toBe(observed)
    })
  }

  it('and only snapshots actually pays for depth', () => {
    const scaling = STRATEGIES
      .filter((s) => grows(observedRetro(s.key, 8), observedRetro(s.key, 32)))
      .map((s) => s.key)
    expect(scaling).toEqual(['snapshots'])
  })
})

describe('the notation column matches the functions', () => {
  const base: CostParams = {
    facts: 100, attrs: 2, horizonDays: 240, snapshotInterval: 30, retroDepth: 0.5,
  }

  for (const [key, model] of Object.entries(COST_MODELS)) {
    it(`${key}: anything labelled O(1) is actually flat in N`, () => {
      for (const measure of ['storage', 'read', 'append', 'retro'] as const) {
        if (model.notation[measure] !== 'O(1)') continue
        const small = model[measure]({ ...base, facts: 10 })
        const large = model[measure]({ ...base, facts: 10_000 })
        expect(large, `${key}.${measure} is labelled O(1) but moves with N`).toBe(small)
      }
    })
  }
})

import { useState } from 'react'
import type { CostParams } from '../core/cost'
import { COST_MODELS, costCurve } from '../core/cost'
import { HORIZON } from '../core/log'
import { STRATEGIES } from '../core/strategies/registry'
import { ATTRS } from '../core/types'
import { seriesColour } from './palette'
import { linear } from './scale'

type Props = {
  snapshotInterval: number
}

type Measure = 'storage' | 'read' | 'append' | 'retro'

const MEASURES: { key: Measure; title: string; axis: string }[] = [
  { key: 'storage', title: 'storage', axis: 'records held' },
  { key: 'read', title: 'read', axis: 'records touched / query' },
  { key: 'append', title: 'append', axis: 'records touched / in-order write' },
  { key: 'retro', title: 'retroactive write', axis: 'records touched / correction' },
]

/** Swept fact counts, log-spaced 10 → 10,000 — the "as history grows" axis. */
const FACT_RANGE = [10, 20, 50, 100, 200, 500, 1_000, 2_000, 5_000, 10_000]
const X_MIN = FACT_RANGE[0]!
const X_MAX = FACT_RANGE.at(-1)!

const CHART_W = 268
const CHART_H = 172
const PAD_L = 28
const PAD_R = 60
const PAD_T = 10
const PAD_B = 20

const ATTRS_COUNT = ATTRS.length
const HORIZON_DAYS = HORIZON.end - HORIZON.start

function formatTick(n: number): string {
  if (n === 0) return '0'
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`
  return `${Math.round(n)}`
}

/**
 * Log-log axes: the fact range spans three orders of magnitude and the
 * measures span more (O(1) beside O(N·A)), so a linear axis would flatten
 * everything under the biggest curve. y uses log1p so a value of exactly 0
 * (e.g. a strategy that charges nothing for retroactive depth) still plots,
 * instead of producing -Infinity.
 */
function xScale(range: [number, number]) {
  const lin = linear([Math.log10(X_MIN), Math.log10(X_MAX)], range)
  return (facts: number) => lin(Math.log10(Math.max(facts, X_MIN)))
}
function y1pScale(maxY: number, range: [number, number]) {
  const lin = linear([0, Math.log10(maxY + 1)], range)
  return (v: number) => lin(Math.log10(v + 1))
}

/** Nudges overlapping right-end line labels apart so every one stays legible. */
function spreadLabels(entries: { key: string; y: number }[], minGap: number): Map<string, number> {
  const sorted = [...entries].sort((a, b) => a.y - b.y)
  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1]!
    const cur = sorted[i]!
    if (cur.y - prev.y < minGap) cur.y = prev.y + minGap
  }
  return new Map(sorted.map((e) => [e.key, e.y]))
}

/**
 * The scale band: how each representation behaves as history grows.
 *
 * An asymptotic table carries the argument on its own; four small-multiple
 * charts (one per measure) show the same argument as curves over a swept
 * number of facts, moved by the two sliders that actually change the
 * mechanics — the snapshot grid (hybrid) and how far back a correction
 * reaches (snapshots).
 */
export function CostPanel({ snapshotInterval }: Props) {
  const [k, setK] = useState(snapshotInterval)
  const [retroDepth, setRetroDepth] = useState(0.4)

  const base: CostParams = {
    facts: 0,
    attrs: ATTRS_COUNT,
    horizonDays: HORIZON_DAYS,
    snapshotInterval: k,
    retroDepth,
  }

  return (
    <div className="panel">
      <p style={{ margin: '0 0 12px', color: 'var(--ink-faint)', fontSize: 12, maxWidth: '70ch' }}>
        Modelled projections, not measurements: closed-form functions of each
        strategy&rsquo;s stated mechanics (see <code>core/cost.ts</code>), not a
        benchmark — nothing here runs a strategy or times anything.
      </p>
      <p style={{ margin: '0 0 12px', color: 'var(--ink-faint)', fontSize: 12, maxWidth: '70ch' }}>
        Growth below is in <strong>N</strong>, the number of facts. Attributes per
        entity (<strong>A</strong>) and horizon length (<strong>H</strong>) are held
        fixed and appear in the notation where a row depends on them, so
        &ldquo;O(1)&rdquo; here means constant in N — not cheap in every dimension.
        The model is held to the implementations by <code>core/costClaims.test.ts</code>,
        which compares how each measure grows against operations the strategies
        actually perform.
      </p>

      <table>
        <thead>
          <tr>
            <th>strategy</th>
            <th>storage</th>
            <th>read</th>
            <th>append</th>
            <th>retroactive</th>
          </tr>
        </thead>
        <tbody>
          {STRATEGIES.map((s) => {
            const model = COST_MODELS[s.key]!
            return (
              <tr key={s.key}>
                <td>
                  <span
                    style={{
                      display: 'inline-block', width: 8, height: 8, borderRadius: '50%',
                      background: seriesColour(s.key), marginRight: 7,
                    }}
                  />
                  {s.name}
                  {!s.correct && <span className="tag wrong" style={{ marginLeft: 7 }}>incorrect</span>}
                </td>
                <td className="num">{model.notation.storage}</td>
                <td className="num">{model.notation.read}</td>
                <td className="num">{model.notation.append}</td>
                <td className="num">{model.notation.retro}</td>
              </tr>
            )
          })}
        </tbody>
      </table>

      <p style={{ margin: '8px 0 0', color: 'var(--ink-faint)', fontSize: 12, maxWidth: '74ch' }}>
        The incorrect strategy&rsquo;s append and retroactive figures are the
        cheapest in this table — that cheapness is the trap, not a
        recommendation. It never invalidates the snapshots it leaves stale.
      </p>

      <div
        style={{
          display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(230px, 1fr))',
          gap: 10, marginTop: 16,
        }}
      >
        {MEASURES.map((m) => (
          <CostChart key={m.key} measureKey={m.key} title={m.title} axisLabel={m.axis} base={base} />
        ))}
      </div>

      <div style={{ display: 'flex', gap: 24, marginTop: 16, flexWrap: 'wrap' }}>
        <label style={{ flex: '1 1 220px', fontSize: 12, color: 'var(--ink-soft)' }}>
          snapshot interval k <span className="num">{k}d</span>
          <input
            type="range" min={1} max={365} value={k}
            onChange={(e) => setK(Number(e.target.value))}
          />
        </label>
        <label style={{ flex: '1 1 220px', fontSize: 12, color: 'var(--ink-soft)' }}>
          retroactive depth d <span className="num">{retroDepth.toFixed(2)}</span>
          <input
            type="range" min={0} max={1} step={0.01} value={retroDepth}
            onChange={(e) => setRetroDepth(Number(e.target.value))}
          />
        </label>
      </div>
    </div>
  )
}

function CostChart({
  measureKey, title, axisLabel, base,
}: {
  measureKey: Measure; title: string; axisLabel: string; base: CostParams
}) {
  const curves = STRATEGIES.map((s) => {
    const model = COST_MODELS[s.key]!
    return { key: s.key, name: s.name, points: costCurve(model[measureKey], base, FACT_RANGE) }
  })

  const maxY = Math.max(1, ...curves.flatMap((c) => c.points.map((p) => p.y)))

  const x = xScale([PAD_L, CHART_W - PAD_R])
  const y = y1pScale(maxY, [CHART_H - PAD_B, PAD_T])

  const xTicks = [10, 100, 1_000, 10_000]
  const yCandidates = [1, 10, 100, 1_000, 10_000, 100_000, 1_000_000]
  const yTicks = [0, ...yCandidates.filter((t) => t <= maxY)].slice(-4)

  const labelPositions = spreadLabels(
    curves.map((c) => ({ key: c.key, y: y(c.points.at(-1)!.y) })),
    9,
  )

  return (
    <div>
      <h3 style={{ marginBottom: 2 }}>{title}</h3>
      <p style={{ margin: '0 0 4px', fontSize: 10.5, color: 'var(--ink-faint)' }}>{axisLabel}</p>
      <svg
        viewBox={`0 0 ${CHART_W} ${CHART_H}`} width="100%" role="img"
        aria-label={`${title} versus number of facts recorded, for all five strategies`}
      >
        {yTicks.map((t) => (
          <g key={t}>
            <line
              x1={PAD_L} x2={CHART_W - PAD_R} y1={y(t)} y2={y(t)}
              stroke="var(--rule)" strokeWidth={1}
            />
            <text x={PAD_L - 4} y={y(t) + 3} fontSize={8} textAnchor="end" fill="var(--ink-faint)">
              {formatTick(t)}
            </text>
          </g>
        ))}

        <line
          x1={PAD_L} x2={CHART_W - PAD_R} y1={CHART_H - PAD_B} y2={CHART_H - PAD_B}
          stroke="var(--rule-strong)"
        />
        {xTicks.map((t) => (
          <text
            key={t} x={x(t)} y={CHART_H - PAD_B + 11} fontSize={8}
            textAnchor="middle" fill="var(--ink-faint)"
          >
            {formatTick(t)}
          </text>
        ))}
        <text
          x={(PAD_L + CHART_W - PAD_R) / 2} y={CHART_H - 2} fontSize={8}
          textAnchor="middle" fill="var(--ink-faint)"
        >
          facts recorded (log scale)
        </text>

        {curves.map((c) => {
          const d = c.points.map((p, i) => `${i === 0 ? 'M' : 'L'}${x(p.x)},${y(p.y)}`).join(' ')
          return <path key={c.key} d={d} fill="none" stroke={seriesColour(c.key)} strokeWidth={2} />
        })}

        {curves.map((c) => (
          <text
            key={c.key} x={CHART_W - PAD_R + 4} y={labelPositions.get(c.key)! + 3}
            fontSize={8} fill="var(--ink-soft)"
          >
            {c.name}
          </text>
        ))}
      </svg>
    </div>
  )
}

import { renderToStaticMarkup } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import { COST_MODELS } from '../core/cost'
import { STRATEGIES } from '../core/strategies/registry'
import { CostPanel } from './CostPanel'
import { seriesColour } from './palette'

/**
 * Static-render checks, in the pattern of src/ui/render.test.tsx: cheap to
 * run, and they catch the failures that matter most for a panel built from
 * closed-form arithmetic over a parameter sweep — a component that throws,
 * geometry that produces NaN or Infinity, or a claim in the table that has no
 * corresponding line in the charts (or vice versa).
 */
const noNaN = (markup: string) => {
  expect(markup).not.toMatch(/NaN/)
  expect(markup).not.toMatch(/Infinity/)
}

describe('CostPanel renders', () => {
  it('without throwing, with no NaN or Infinity in the markup', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    noNaN(markup)
  })

  it('every strategy name appears', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    for (const s of STRATEGIES) {
      expect(markup).toContain(s.name)
    }
  })

  it('every notation string from COST_MODELS appears', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    for (const model of Object.values(COST_MODELS)) {
      expect(markup).toContain(model.notation.storage)
      expect(markup).toContain(model.notation.read)
      expect(markup).toContain(model.notation.append)
      expect(markup).toContain(model.notation.retro)
    }
  })

  it('every one of the five series hues appears (all five lines drawn)', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    for (const s of STRATEGIES) {
      expect(markup).toContain(seriesColour(s.key))
    }
  })

  it('every line carries a direct label: each strategy name appears at least twice', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    for (const s of STRATEGIES) {
      const occurrences = markup.split(s.name).length - 1
      expect(occurrences).toBeGreaterThanOrEqual(2)
    }
  })

  it('marks the incorrect strategy as such', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    const incorrect = STRATEGIES.filter((s) => !s.correct)
    expect(incorrect.length).toBeGreaterThan(0)
    expect(markup).toContain('incorrect')
    for (const s of incorrect) {
      expect(markup).toContain(s.name)
    }
  })

  it('states that the figures are modelled, not measured', () => {
    const markup = renderToStaticMarkup(<CostPanel snapshotInterval={30} />)
    expect(markup.toLowerCase()).toContain('modelled')
    expect(markup.toLowerCase()).toContain('not measurements')
  })

  it('renders for extreme snapshotInterval values without NaN', () => {
    noNaN(renderToStaticMarkup(<CostPanel snapshotInterval={1} />))
    noNaN(renderToStaticMarkup(<CostPanel snapshotInterval={365} />))
  })
})

